from config import TAX_RATE, BOOK_DISCOUNT


def total(prices, kinds=None):
    """计算含税总价：图书类先按 BOOK_DISCOUNT 折扣，再按 TAX_RATE 计税。"""
    if kinds is None:
        kinds = ["misc"] * len(prices)
    subtotal = sum(
        p * (1 - BOOK_DISCOUNT) if k == "book" else p
        for p, k in zip(prices, kinds)
    )
    return round(subtotal * (1 + TAX_RATE), 2)
